Lemma rw_cells_hd : forall segs (m : word -> option byte) A c cs, rw_cells segs m A (c :: cs) ->
  forall B, B = (A + Z.of_nat (csize c))%Z -> rw_cells segs m A [c] /\ rw_cells segs m B cs.
Proof.
  intros segs m A c cs H B ->. change (c :: cs) with ([c] ++ cs) in H.
  apply (proj1 (rw_cells_app2 segs m A [c] cs)) in H. cbn [cells_size] in H. rewrite Nat.add_0_r in H. exact H.
Qed.

Section FCZ.
  Variables (cx : cctx) (e : est) (Q : machine_state -> Prop).
  Variables (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (lp : zarr).
  Variables (SP : Z).
  Hypothesis CX : cctx_ok cx.
  Hypothesis CEP : (CEIL <= SP)%Z. Hypothesis PHI : (SP + 1200 <= 18446744073709551616)%Z.
  Notation E := (c_E cx). Notation A1 := (c_A1 cx).
  Notation arr1 := (e_arr1 e). Notation A := (sm_alpha e). Notation nG := (smA_ng e). Notation nMTF := (sm_nmtf e).
  Hypothesis HA : (3 <= A <= 258)%Z. Hypothesis HM : (1 <= nMTF <= (NBLOCKMAX + 20))%Z.
  Hypothesis ZB : zbok arr1.
  Notation S0v := (Z_to_bv 64 E). Notation S1v := (Z_to_bv 64 257). Notation S3v := (Z_to_bv 64 1548).
  Notation S4v := (Z_to_bv 64 (258 * nG)). Notation S9v := (Z_to_bv 64 (18446744073709551615 - (E + 37708))).
  Ltac clear_mem :=
    repeat match goal with
    | Hc : rw_cells _ _ _ _ |- _ => clear Hc
    | Hc : u8arr _ _ _ _ |- _ => clear Hc
    | Hc : mem_inv _ _ |- _ => clear Hc
    | Hc : munch _ _ _ |- _ => clear Hc
    | Hc : wmono _ _ _ |- _ => clear Hc
    end.

